use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let input_obj = input.as_object().unwrap();
    let pattern = input_obj.get("pattern").unwrap().as_str().unwrap();
    let text = input_obj.get("text").unwrap().as_str().unwrap();

    let mut indices = Vec::new();
    let mut start = 0;

    while let Some(position) = text[start..].find(pattern) {
        indices.push(start + position as i64);
        start += position + 1;
    }

    json!(indices)
}
